#!/usr/bin/env python3
"""apply_welle1.py - one self-applying fix file for the WebMonitor project ("Welle 1": foundation).

Run it from the project folder (the one that contains webmonitor/ and monitor_system.py):

    python apply_welle1.py --dry-run     # show what would change, write nothing
    python apply_welle1.py               # apply, syntax-check, run the tests
    python apply_welle1.py --rollback "<backup folder>"   # undo (the folder is printed when applying)

Safety: nothing is written unless every change matches the analysed version of its file (SHA-256 check);
the originals are copied to a backup folder first; a syntax error rolls everything back automatically.
Line endings (LF/CRLF) of existing files are preserved.
"""

from __future__ import annotations

import hashlib
import json
import os
import shutil
import subprocess
import sys
import time
from pathlib import Path

BOM = b"\xef\xbb\xbf"


class PatchError(Exception):
    pass


def sha(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def read_file(path: Path) -> tuple[str, bool, bool]:
    """(text with LF newlines, had CRLF, had BOM)."""
    raw = path.read_bytes()
    bom = raw.startswith(BOM)
    if bom:
        raw = raw[len(BOM):]
    crlf = b"\r\n" in raw
    return raw.decode("utf-8").replace("\r\n", "\n"), crlf, bom


def write_file(path: Path, text: str, crlf: bool = False, bom: bool = False) -> None:
    data = text.replace("\n", "\r\n") if crlf else text
    raw = (BOM if bom else b"") + data.encode("utf-8")
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".welle1.tmp")
    tmp.write_bytes(raw)
    os.replace(tmp, path)


def apply_hunks(name: str, text: str, hunks: list[tuple[str, str]]) -> str:
    """Replace every anchor text by its new text. Anchors are located in the ORIGINAL text, each must
    occur exactly once and they must not overlap, so the result does not depend on their order."""
    spots = []
    for number, (old, new) in enumerate(hunks, 1):
        count = text.count(old)
        if count != 1:
            raise PatchError(f"{name}: change #{number} anchor found {count}x (expected exactly 1x): "
                             f"{old.strip().splitlines()[0][:80]!r}")
        spots.append((text.index(old), old, new, number))
    spots.sort()
    for (a_start, a_old, _n, a_no), (b_start, _o, _n2, b_no) in zip(spots, spots[1:]):
        if a_start + len(a_old) > b_start:
            raise PatchError(f"{name}: changes #{a_no} and #{b_no} overlap")
    out, pos = [], 0
    for start, old, new, _number in spots:
        out.append(text[pos:start])
        out.append(new)
        pos = start + len(old)
    out.append(text[pos:])
    return "".join(out)


def plan(root: Path, ops: list[dict], force: bool = False, git_root: Path | None = None) -> list[dict]:
    """Compute every result in memory first. Raises PatchError before anything is written."""
    steps = []
    problems = []
    for op in ops:
        rel, kind = op["path"], op["kind"]
        if kind == "ci":
            if git_root is None:
                steps.append({"op": op, "action": "skip", "why": "no git repository found above the project folder"})
                continue
            target = git_root / rel
            work = os.path.relpath(root, git_root).replace(os.sep, "/")
            content = op["content"].replace("{WORKDIR}", work)
            if target.exists() and read_file(target)[0] == content:
                steps.append({"op": op, "action": "same", "target": target})
            else:
                steps.append({"op": op, "action": "write", "target": target, "text": content,
                              "crlf": False, "bom": False, "existed": target.exists()})
            continue
        target = root / rel
        if kind == "new":
            if target.exists() and sha(read_file(target)[0]) == op["post"]:
                steps.append({"op": op, "action": "same", "target": target})
            else:
                steps.append({"op": op, "action": "write", "target": target, "text": op["content"],
                              "crlf": False, "bom": False, "existed": target.exists()})
            continue
        if not target.exists():
            problems.append(f"{rel}: file not found - run the script from the project folder (the one with webmonitor/)")
            continue
        text, crlf, bom = read_file(target)
        current = sha(text)
        if current == op["post"]:
            steps.append({"op": op, "action": "same", "target": target})
            continue
        if current != op["pre"] and not force:
            problems.append(f"{rel}: differs from the version that was analysed (git pull first, or use --force "
                            f"if only unrelated lines changed)")
            continue
        try:
            new_text = op["content"] if kind == "replace" else apply_hunks(rel, text, op["hunks"])
        except PatchError as exc:
            problems.append(str(exc))
            continue
        if sha(new_text) != op["post"] and not force:
            problems.append(f"{rel}: result does not match the tested version")
            continue
        steps.append({"op": op, "action": "write", "target": target, "text": new_text, "crlf": crlf, "bom": bom,
                      "existed": True})
    if problems:
        raise PatchError("\n  ".join(["Nothing was changed. Problems:"] + problems))
    return steps


def run(root: Path, ops: list[dict], *, force=False, dry_run=False, run_tests=True, git_root=None, log=print) -> int:
    steps = plan(root, ops, force=force, git_root=git_root)
    writes = [s for s in steps if s["action"] == "write"]
    for s in steps:
        rel = s["op"]["path"]
        if s["action"] == "same":
            log(f"  = {rel}  (already up to date)")
        elif s["action"] == "skip":
            log(f"  - {rel}  (skipped: {s['why']})")
        else:
            log(f"  {'~' if s['existed'] else '+'} {rel}")
    if dry_run:
        log("\nDry run: nothing was written.")
        return 0
    if not writes:
        log("\nEverything is already applied.")
        return 0

    stamp = time.strftime("%Y%m%d-%H%M%S")
    backup = Path.home() / f"webmonitor-welle1-backup-{stamp}"
    try:
        backup.mkdir(parents=True)
    except OSError:
        backup = root / f"_backup_welle1_{stamp}"
        backup.mkdir(parents=True)
    manifest = {"root": str(root), "modified": [], "created": []}
    for s in writes:
        target = s["target"]
        key = str(target)
        if s["existed"]:
            dest = backup / "files" / hashlib.sha1(key.encode()).hexdigest()
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, dest)
            manifest["modified"].append({"target": key, "saved": str(dest)})
        else:
            manifest["created"].append(key)
    (backup / "manifest.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    log(f"\nBackup of the originals: {backup}")

    try:
        for s in writes:
            write_file(s["target"], s["text"], s["crlf"], s["bom"])
        compiled = [str(s["target"]) for s in writes if str(s["target"]).endswith(".py")]
        if compiled:
            check = subprocess.run([sys.executable, "-m", "py_compile", *compiled], capture_output=True, text=True)
            if check.returncode != 0:
                raise PatchError("syntax check failed:\n" + check.stderr[-1500:])
    except Exception as exc:
        log(f"\nERROR while applying: {exc}\nRolling back ...")
        rollback(backup, log=log)
        return 2
    log(f"\nApplied {len(writes)} file(s). Syntax check passed.")

    if run_tests and (root / "tests").is_dir():
        probe = subprocess.run([sys.executable, "-c", "import aiohttp, lxml, regex, cssselect"], capture_output=True)
        if probe.returncode != 0:
            log("\nTests skipped: install the pinned libraries first:\n"
                f"    {sys.executable} -m pip install -r requirements.txt\n"
                "then run:   python -m unittest discover -s tests")
            return 0
        log("\nRunning the test-suite ...")
        env = dict(os.environ, WEBMONITOR_SKIP_BROWSER="1", PYTHONIOENCODING="utf-8")
        result = subprocess.run([sys.executable, "-m", "unittest", "discover", "-s", "tests"], cwd=root, env=env,
                                capture_output=True, text=True, encoding="utf-8", errors="replace")
        tail = (result.stderr or result.stdout).strip().splitlines()[-6:]
        log("\n".join("    " + line for line in tail))
        if result.returncode != 0:
            log("\nTests FAILED. To undo everything:  python " + Path(sys.argv[0]).name + f" --rollback \"{backup}\"")
            return 1
        log("\nAll tests passed.")
    return 0


def rollback(backup: Path, log=print) -> None:
    manifest = json.loads((Path(backup) / "manifest.json").read_text(encoding="utf-8"))
    for item in manifest["modified"]:
        shutil.copy2(item["saved"], item["target"])
        log(f"  restored {item['target']}")
    for target in manifest["created"]:
        try:
            Path(target).unlink()
            log(f"  removed  {target}")
        except FileNotFoundError:
            pass


